INSERT INTO weekly_updates VALUES(18,4,'2025-08-25','{"style":"checklist","meta":{},"items":[{"content":"Major breakthrough: reduced Apple I chip count from 60 to 45 chips","meta":{"checked":true},"items":[{"content":"Discovered elegant way to multiplex the timing circuits","meta":{"checked":true},"items":[]},{"content":"Saved $80 per board in component costs","meta":{"checked":true},"items":[]},{"content":"Lost track of time and missed my sister''s birthday dinner","meta":{"checked":false},"items":[]}]},{"content":"Homebrew Computer Club presentation on dynamic memory refresh","meta":{"checked":true},"items":[{"content":"Distributed 20 copies of complete schematics for free","meta":{"checked":true},"items":[]},{"content":"Got standing ovation for the elegance of the design","meta":{"checked":true},"items":[]},{"content":"Jobs keeps telling me I''m crazy for giving it away","meta":{"checked":false},"items":[]}]},{"content":"Built working prototype of new keyboard interface using only 8 chips","meta":{"checked":true},"items":[{"content":"Previous designs from other hobbyists used 30-40 chips","meta":{"checked":true},"items":[]},{"content":"Documented entire design process in 15-page technical manual","meta":{"checked":true},"items":[]}]},{"content":"HP work suffering from late night hardware sessions","meta":{"checked":false},"items":[{"content":"Called in sick twice this week to work on computer","meta":{"checked":false},"items":[]},{"content":"Manager starting to ask questions about my energy levels","meta":{"checked":false},"items":[]},{"content":"Still completed calculator display driver ahead of schedule","meta":{"checked":true},"items":[]}]},{"content":"Taught 3 Homebrew members how to implement my TV interface design","meta":{"checked":true},"items":[]},{"content":"Apartment is complete disaster - haven''t cleaned in 2 weeks, just circuit boards everywhere","meta":{"checked":false},"items":[]}]}','2025-08-28 00:12:32','2025-08-28 00:12:32','Productive week - keyboard interface and color graphics boards done','7');
INSERT INTO weekly_updates VALUES(19,4,'2025-08-18','{"style":"checklist","meta":{},"items":[{"content":"Completed first fully functional Apple I board","meta":{"checked":true},"items":[{"content":"Boots to monitor prompt in under 2 seconds","meta":{"checked":true},"items":[]},{"content":"Successfully ran BASIC interpreter for 48 hours straight","meta":{"checked":true},"items":[]},{"content":"Burned my finger pretty badly on the soldering iron during hour 30","meta":{"checked":false},"items":[]}]},{"content":"Revolutionary discovery: can use shift registers to cut video generation cost by 75%","meta":{"checked":true},"items":[{"content":"Wrote detailed technical paper explaining the approach","meta":{"checked":true},"items":[]},{"content":"Other engineers at HP think I''m wasting my talent on \"toys\"","meta":{"checked":false},"items":[]}]},{"content":"Helped 6 Homebrew members debug their Altair memory boards","meta":{"checked":true},"items":[{"content":"Created universal diagnostic program that anyone can use","meta":{"checked":true},"items":[]},{"content":"Refused payment - just happy to see people building","meta":{"checked":true},"items":[]}]},{"content":"Steve Jobs situation getting complicated","meta":{"checked":false},"items":[{"content":"He sold his van to buy components but I just wanted to give boards away","meta":{"checked":false},"items":[]},{"content":"Now he''s talking about starting a company - I just want to engineer","meta":{"checked":false},"items":[]},{"content":"Agreed to let him handle \"business stuff\" so I can focus on design","meta":{"checked":true},"items":[]}]},{"content":"Designed elegant power supply using switching regulators (first for a personal computer)","meta":{"checked":true},"items":[]},{"content":"Haven''t slept more than 4 hours a night in 2 weeks","meta":{"checked":false},"items":[]}]}','2025-08-28 00:12:32','2025-08-28 00:12:32','Two boards completed: memory expansion and video display','5');
